    @Test func arithmeticMatchesPython() throws {
        for c in Self.cases {
            let a = try #require(BigUInt(hex: c.a)), b = try #require(BigUInt(hex: c.b))
            let m = try #require(BigUInt(hex: c.m)), e = try #require(BigUInt(hex: c.e))
            #expect(a * b == BigUInt(hex: c.product))
            #expect(a % m == BigUInt(hex: c.remainder))
            #expect(a.power(e, modulus: m) == BigUInt(hex: c.power))
            #expect((a + b) - b == a)
        }
    }

    @Test func bytesRoundTripAndPad() {
        let x = BigUInt(bytes: [0, 0, 1, 2, 3])
        #expect(x.bytes() == [1, 2, 3])
        #expect(x.bytes(length: 6) == [0, 0, 0, 1, 2, 3])
        #expect(BigUInt(bytes: []).isZero)
        #expect(BigUInt(0x0102030405060708).bytes() == [1, 2, 3, 4, 5, 6, 7, 8])
    }
